REQ_RPO = 60
REQ_RTO = 120

STRATEGIES = [
    {"name": "backup-restore", "rpo": 1440, "rto": 1440},
    {"name": "pilot-light", "rpo": 30, "rto": 240},
    {"name": "warm-standby", "rpo": 5, "rto": 30},
    {"name": "multi-site", "rpo": 0, "rto": 1},
]

def evaluate(strategy, req_rpo, req_rto):
    if strategy["rpo"] > req_rpo:
        return "FAIL (rpo)"
    if strategy["rto"] > req_rto:
        return "FAIL (rto)"
    return "PASS"

def select(strategies, req_rpo, req_rto):
    for s in strategies:
        if evaluate(s, req_rpo, req_rto) == "PASS":
            return s["name"]
    return None

for s in STRATEGIES:
    print(f"{s['name']}: {evaluate(s, REQ_RPO, REQ_RTO)}")
print(f"selected={select(STRATEGIES, REQ_RPO, REQ_RTO)}")
